css:
atlas-page{--atlas-page-width:78rem} .kb-header{padding:.3rem 0 1.2rem;border-bottom:1px solid var(--atlas-border)} .kb-kicker{letter-spacing:.15em;text-transform:uppercase;font-size:.72rem;font-weight:750;color:var(--atlas-muted)} .kb-header-main{display:flex;align-items:end;justify-content:space-between;gap:1.2rem;flex-wrap:wrap}.kb-header h1{font-size:clamp(1.8rem,3.5vw,2.6rem);letter-spacing:-.04em;line-height:1.15;margin:.55rem 0 .35rem}.kb-header p,.kb-sectionhead p{margin:0;color:var(--atlas-muted);line-height:1.55}.kb-counts{display:flex;gap:.75rem;flex-wrap:wrap;color:var(--atlas-muted);font-size:.77rem}.kb-counts span{padding:.45rem .7rem;border-radius:10px;background:var(--atlas-surface);border:1px solid var(--atlas-border)}.kb-counts strong{font-size:1rem;color:var(--atlas-text)}.kb-searcharea{background:var(--atlas-surface);border:1px solid var(--atlas-border);border-radius:var(--atlas-radius);padding:1.1rem;margin:1.25rem 0 1.4rem}.kb-searcharea label{font-size:.78rem;color:var(--atlas-muted);font-weight:650;display:block;margin-bottom:.35rem}.kb-searcharea input,.kb-searcharea select{width:100%;min-width:0;padding:.72rem .8rem;border:1px solid var(--atlas-border);border-radius:9px;background:var(--atlas-bg);color:var(--atlas-text);font:inherit}.kb-searcharea input:focus,.kb-searcharea select:focus{outline:2px solid var(--atlas-accent);outline-offset:1px}.kb-mainsearch input{font-size:1.04rem}.kb-filters{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:.65rem;margin-top:1rem}.kb-search-footer{display:flex;gap:.7rem;align-items:center;justify-content:space-between;margin-top:.7rem}.kb-search-footer p{font-size:.78rem;color:var(--atlas-muted);margin:0}.kb-search-footer button{border:0;background:transparent;color:var(--atlas-accent);padding:.35rem;cursor:pointer;font-weight:650}.kb-sectionhead{margin:.2rem 0 1rem}.kb-sectionhead h2{font-size:1.2rem;letter-spacing:-.025em;margin:0 0 .2rem}.kb-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem}.kb-item{border:1px solid var(--atlas-border);background:var(--atlas-surface);padding:1rem 1.1rem;border-radius:var(--atlas-radius);min-width:0}.kb-entry-top{display:flex;justify-content:space-between;align-items:flex-start;gap:.75rem}.kb-entry h3,.kb-item h3{font-size:1rem;line-height:1.4;letter-spacing:-.01em;margin:0}.kb-summary{line-height:1.65;font-size:.91rem;color:var(--atlas-text);margin:.6rem 0}.kb-meta{display:flex;flex-wrap:wrap;gap:.35rem .6rem;color:var(--atlas-muted);font-size:.76rem;overflow-wrap:anywhere}.kb-meta span:not(:last-child)::after{content:' ·';margin-left:.35rem}.kb-item details{border-top:1px solid var(--atlas-border);margin-top:.8rem;padding-top:.6rem;font-size:.88rem;line-height:1.6}.kb-item summary{cursor:pointer;color:var(--atlas-accent);font-weight:650}.kb-detail{white-space:pre-wrap;margin:.7rem 0}.kb-excerpt{border-left:2px solid var(--atlas-border);padding-left:.7rem;color:var(--atlas-muted)}.kb-detail-meta,.kb-footnote{color:var(--atlas-muted);font-size:.76rem}.kb-item a{color:var(--atlas-accent);overflow-wrap:anywhere}.kb-item[hidden]{display:none!important}.kb-tab{padding-top:.85rem}.kb-footnote{padding:1.3rem 0;max-width:50rem;line-height:1.6}.kb-source-link{font-size:.86rem}#kb-empty-filter{color:var(--atlas-muted);font-size:.86rem}@media(max-width:920px){.kb-filters{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:690px){.kb-list{grid-template-columns:1fr}.kb-filters{grid-template-columns:1fr}.kb-header-main{align-items:start}}
.kb-open{width:100%;text-align:left;color:inherit;background:transparent;border:0;padding:0;font:inherit;cursor:pointer}
.kb-open:focus-visible,.kb-reader-close:focus-visible{outline:2px solid var(--atlas-accent);outline-offset:4px}
.kb-read-more{margin-top:.85rem;padding-top:.65rem;border-top:1px solid var(--atlas-border);font-size:.82rem;color:var(--atlas-accent);font-weight:700}
.kb-open:hover .kb-read-more{text-decoration:underline}
.kb-reader{box-sizing:border-box;width:min(850px,calc(100vw - 30px));max-width:calc(100vw - 30px);max-height:90vh;margin:auto;padding:0;border-radius:14px;border:1px solid var(--atlas-border);background:var(--atlas-bg);color:var(--atlas-text);overflow:auto;box-shadow:0 25px 80px rgba(0,0,0,.23)}
.kb-reader::backdrop{background:rgba(0,0,0,.62)}
.kb-reader-body{padding:0 clamp(18px,4vw,45px) 35px}
.kb-reader-top{display:flex;gap:15px;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:1;background:var(--atlas-bg);border-bottom:1px solid var(--atlas-border);padding:15px 0;color:var(--atlas-muted);font-size:.72rem;letter-spacing:.11em;font-weight:700}
.kb-reader-close{padding:9px 13px;border:1px solid var(--atlas-border);border-radius:7px;background:var(--atlas-surface);color:var(--atlas-text);font:inherit;font-size:.82rem;letter-spacing:normal;cursor:pointer}
.kb-reader h2{font-size:clamp(1.35rem,3vw,2rem);letter-spacing:-.03em;line-height:1.3;margin:25px 0 13px}
.kb-badges{display:flex;flex-wrap:wrap;gap:7px}.kb-badges span{font-size:.72rem;padding:5px 8px;border:1px solid var(--atlas-border);background:var(--atlas-surface);border-radius:5px;color:var(--atlas-muted)}
.kb-reader section{margin-top:23px;padding-top:17px;border-top:1px solid var(--atlas-border)}
.kb-reader section h3{font-size:.76rem;letter-spacing:.08em;text-transform:uppercase;color:var(--atlas-muted);margin:0 0 12px}
.kb-reader section p{font-size:.96rem;line-height:1.82;margin:0;white-space:pre-wrap}
.kb-reader .kb-quote-section{padding:20px;border-radius:10px;background:var(--atlas-surface);border:1px solid var(--atlas-border)}
.kb-reader blockquote{margin:0;padding-left:16px;border-left:3px solid var(--atlas-accent);line-height:1.8;font-size:1.07rem;font-weight:500;white-space:pre-wrap}
.kb-reader .kb-evidence-note{margin-top:13px;color:var(--atlas-muted);font-size:.77rem}
.kb-reader dl{display:grid;grid-template-columns:110px minmax(0,1fr);gap:12px;font-size:.83rem;line-height:1.55;overflow-wrap:anywhere}
.kb-reader dt{font-weight:700;color:var(--atlas-muted)}.kb-reader dd{margin:0}
.kb-reader a{color:var(--atlas-accent);font-weight:700}
@media(max-width:640px){.kb-reader{max-height:95vh}.kb-reader-body{padding:0 18px 24px}.kb-reader .kb-quote-section{padding:14px}.kb-reader dl{grid-template-columns:85px minmax(0,1fr)}}

.kb-mainsearch{display:flex;flex-wrap:wrap;gap:.5rem;align-items:end}
.kb-mainsearch label{flex-basis:100%}
.kb-mainsearch input{flex:1;min-width:220px}
.kb-mainsearch button,.kb-pagination button,.kb-pick-source{border:1px solid var(--atlas-border);background:var(--atlas-surface);border-radius:7px;padding:.73rem .85rem;color:var(--atlas-text);font:inherit;cursor:pointer}
.kb-mainsearch button{background:var(--atlas-accent);color:white;border-color:var(--atlas-accent);font-weight:700}
.kb-pagination{display:flex;justify-content:space-between;gap:.9rem;flex-wrap:wrap;align-items:center;padding:1rem 0;margin-top:.9rem;color:var(--atlas-muted);font-size:.8rem}
.kb-pagination>div{display:flex;gap:.5rem}
.kb-pagination button{padding:.5rem .75rem}
.kb-pagination button:disabled{opacity:.4;cursor:default}
.kb-pick-source{margin:.8rem 0 .4rem;color:var(--atlas-accent);font-size:.82rem;font-weight:700;padding:.4rem .7rem}

script:
atlas.onReady(()=>{
 const pairs=[
  {name:'q',input:document.getElementById('kb-search'),value:atlas.params.q},
  {name:'group',input:document.getElementById('kb-group'),value:atlas.params.group},
  {name:'source',input:document.getElementById('kb-source'),value:atlas.params.source},
  {name:'sourceType',input:document.getElementById('kb-type'),value:atlas.params.sourceType},
  {name:'kind',input:document.getElementById('kb-kind'),value:atlas.params.kind},
  {name:'tag',input:document.getElementById('kb-tags'),value:atlas.params.tag}
 ];
 pairs.forEach(item=>{item.input.value=item.value||'';});
 const offsets=['entryOffset','sourceOffset','sectionOffset','relationOffset'];
 function commit(){
  pairs.forEach(item=>atlas.setParam(item.name,item.input.value.trim()));
  offsets.forEach(key=>atlas.setParam(key,'0'));
  atlas.refresh();
 }
 document.getElementById('kb-search-submit').addEventListener('click',commit);
 const search=document.getElementById('kb-search');
 search.addEventListener('keydown',event=>{if(event.key==='Enter')commit();});
 document.getElementById('kb-group').addEventListener('change',commit);
 document.getElementById('kb-source').addEventListener('change',commit);
 document.getElementById('kb-type').addEventListener('change',commit);
 document.getElementById('kb-kind').addEventListener('change',commit);
 document.getElementById('kb-tags').addEventListener('keydown',event=>{if(event.key==='Enter')commit();});
 document.getElementById('kb-reset').addEventListener('click',()=>{
  pairs.forEach(item=>item.input.value='');
  commit();
 });
 const pagerDefs=[
  {name:'entries',param:'entryOffset',page:atlas.data.entriesPage[0]},
  {name:'sources',param:'sourceOffset',page:atlas.data.sourcesPage[0]},
  {name:'sections',param:'sectionOffset',page:atlas.data.sectionsPage[0]},
  {name:'relations',param:'relationOffset',page:atlas.data.relationsPage[0]}
 ];
 pagerDefs.forEach(info=>{
  const panel=document.querySelector('.kb-pagination[data-pager="'+info.name+'"]');
  if(!panel || !info.page)return;
  const prev=panel.querySelector('.kb-prev');
  const next=panel.querySelector('.kb-next');
  prev.disabled=!info.page.hasPrevious;
  next.disabled=!info.page.hasNext;
  prev.addEventListener('click',()=>{atlas.setParam(info.param,String(Math.max(0,info.page.offset-info.page.limit)));atlas.refresh();});
  next.addEventListener('click',()=>{atlas.setParam(info.param,String(info.page.offset+info.page.limit));atlas.refresh();});
 });
 document.querySelectorAll('.kb-pick-source').forEach(button=>{
  button.addEventListener('click',()=>{
   const key=button.parentElement.getAttribute('data-id');
   if(!key)return;
   atlas.setParam('source',key);
   atlas.setParam('q','');
   offsets.forEach(name=>atlas.setParam(name,'0'));
   atlas.refresh();
  });
 });
 document.querySelectorAll('.kb-open').forEach(button=>{
  button.addEventListener('click',()=>{
   const dialog=button.parentElement.querySelector('dialog.kb-reader');
   if(dialog)dialog.showModal();
  });
 });
 document.querySelectorAll('.kb-reader-close').forEach(button=>{
  button.addEventListener('click',()=>{
   const dialog=button.closest('dialog.kb-reader');
   if(dialog)dialog.close();
  });
 });
});
